-- V5's first unnamed CHECK is generated by MySQL as integration_outbox_chk_1.
-- Replace only that CHECK, atomically; preserve rows and the other outbox rules.
ALTER TABLE integration_outbox
    DROP CHECK integration_outbox_chk_1,
    ADD CONSTRAINT chk_outbox_kind
        CHECK (kind IN ('CONFIGURATION', 'CREDENTIALS', 'ACCESS_RESULT', 'ALARM'));
